+++ b/src/query.ts
@@ -1,6 +1,36 @@
 export type Query = Record<string, string | string[]>;
+
+function decodePart(part: string): string {
+  const spaced = part.replace(/\+/g, " ");
+  try {
+    return decodeURIComponent(spaced);
+  } catch {
+    return spaced;
+  }
+}

 /** Parse a URL query string. See README.md for the rules. */
 export function parseQuery(query: string): Query {
-  throw new Error("not implemented");
+  const body = query.startsWith("?") ? query.slice(1) : query;
+  const result: Query = {};
+  if (body === "") return result;
+
+  for (const pair of body.split("&")) {
+    if (pair === "") continue;
+    const eq = pair.indexOf("=");
+    const key = decodePart(eq === -1 ? pair : pair.slice(0, eq));
+    const value = eq === -1 ? "" : decodePart(pair.slice(eq + 1));
+
+    if (!Object.prototype.hasOwnProperty.call(result, key)) {
+      Object.defineProperty(result, key, { value, enumerable: true, writable: true, configurable: true });
+    } else {
+      const existing = result[key];
+      if (Array.isArray(existing)) {
+        existing.push(value);
+      } else {
+        result[key] = [existing, value];
+      }
+    }
+  }
+  return result;
 }
